import 'dart:async';

import 'package:dio/dio.dart';

import '../domain/models.dart';
import 'recipe_import.dart';

class RecipeMatch {
  RecipeMatch(this.recipe, this.score, this.have, this.missing, {this.verified = true});
  final Recipe recipe;

  /// 0..1: share of the recipe's ingredients that are in the pantry.
  final double score;
  final List<String> have, missing;

  /// true = taken from a real web page, false = generated by AI.
  final bool verified;
}

/// Ingredients people always have; they don't count against a recipe.
const defaultStaples = ['sól', 'pieprz', 'woda', 'olej', 'cukier'];

const _noise = {
  'g', 'kg', 'dag', 'ml', 'l', 'szklanka', 'szklanki', 'szklankę', 'łyżka', 'łyżki', 'łyżkę', 'łyżeczka',
  'łyżeczki', 'łyżeczkę', 'szczypta', 'szczypty', 'ząbek', 'ząbki', 'ząbków', 'plaster', 'plastry', 'plasterki',
  'sztuka', 'sztuki', 'sztuk', 'szt', 'opakowanie', 'kostka', 'kostki', 'pęczek', 'garść', 'garści', 'puszka',
  'puszki', 'dużego', 'duży', 'duża', 'duże', 'mały', 'mała', 'małe', 'małego', 'średni', 'średnia', 'średnie',
  'świeży', 'świeża', 'świeże', 'świeżego', 'świeżych', 'zmielony', 'zmielonego', 'drobno', 'posiekany',
  'posiekane', 'pokrojony', 'pokrojona', 'pokrojone', 'starty', 'tarty', 'ok', 'około', 'do', 'smaku', 'oraz',
  'lub', 'albo', 'na', 'ze', 'z', 'i', 'w', 'po', 'dla', 'czubata', 'płaska', 'gładka', 'taka', 'trochę',
  'więcej', 'mniej', 'odrobina', 'kawałek', 'kawałka', 'cm', 'litr', 'litra', 'gram', 'gramów', 'mililitrów',
  'opcjonalnie', 'dekoracji', 'podania', 'posypania', 'smażenia', 'wody', 'jak',
};

String _norm(String t) {
  t = t.toLowerCase();
  if (t.startsWith('jaj')) return 'jajko';
  return t;
}

List<String> ingredientTokens(String line) {
  var s = line.toLowerCase().replaceAll(RegExp(r'\(.*?\)'), ' ');
  s = s.replaceAll(RegExp(r'[\d½¼¾.,/\-–:;]+'), ' ');
  return s
      .split(RegExp(r'\s+'))
      .map((e) => e.replaceAll(RegExp(r'[^a-ząćęłńóśźż]'), ''))
      .where((t) => t.length >= 3 && !_noise.contains(t))
      .map(_norm)
      .toList();
}

bool _same(String a, String b) {
  if (a == b) return true;
  final minLen = a.length < b.length ? a.length : b.length;
  var i = 0;
  while (i < minLen && a[i] == b[i]) {
    i++;
  }
  return i >= (minLen < 4 ? minLen : 4) && minLen >= 3;
}

RecipeMatch matchRecipe(Recipe r, List<String> pantry, {List<String> staples = defaultStaples, bool verified = true}) {
  final have = <String>{for (final p in [...pantry, ...staples]) ...ingredientTokens(p)};
  final h = <String>[], m = <String>[];
  for (final line in r.ingredients) {
    final low = line.toLowerCase();
    if (low.contains('opcjonalnie') || low.contains('do dekoracji') || low.contains('do podania')) continue;
    final toks = ingredientTokens(line);
    if (toks.isEmpty) continue;
    // A line is covered if its main (first) content word is in the pantry;
    // qualifiers like "ser żółty" still match on "ser".
    final ok = toks.any((t) => have.any((p) => _same(t, p)));
    (ok ? h : m).add(line);
  }
  final total = h.length + m.length;
  return RecipeMatch(r, total == 0 ? 0 : h.length / total, h, m, verified: verified);
}

/// Real recipes from the web, never generated: Kwestia Smaku's own search
/// (no key) and, if a key is given, Brave Search over the whole web. Pages are
/// parsed from schema.org Recipe data and the match % is computed locally.
class RecipeWebSearch {
  RecipeWebSearch({Dio? dio, this.braveKey})
      : _dio = dio ??
            Dio(BaseOptions(
              connectTimeout: const Duration(seconds: 10),
              receiveTimeout: const Duration(seconds: 20),
              headers: {'User-Agent': 'Mozilla/5.0 (Linux; Android 14) Chrome/120 Mobile Safari/537.36'},
            ));
  final Dio _dio;
  final String? braveKey;

  Future<List<String>> _kwestia(String q) async {
    try {
      final r = await _dio.get<String>('https://www.kwestiasmaku.com/szukaj',
          queryParameters: {'search_api_views_fulltext': q},
          options: Options(responseType: ResponseType.plain));
      final re = RegExp(r'href="(/[^"]*?/przepis\.html)"');
      return {for (final m in re.allMatches(r.data ?? '')) 'https://www.kwestiasmaku.com${m.group(1)}'}.toList();
    } catch (_) {
      return [];
    }
  }

  Future<List<String>> _brave(String q) async {
    if (braveKey == null || braveKey!.isEmpty) return [];
    try {
      final r = await _dio.get('https://api.search.brave.com/res/v1/web/search',
          queryParameters: {'q': 'przepis $q', 'country': 'pl', 'search_lang': 'pl', 'count': 12},
          options: Options(headers: {'X-Subscription-Token': braveKey, 'Accept': 'application/json'}));
      final results = ((r.data as Map)['web']?['results'] as List?) ?? const [];
      return [for (final e in results) '${(e as Map)['url']}'];
    } catch (_) {
      return [];
    }
  }

  Future<List<RecipeMatch>> search(List<String> pantry, {int maxPages = 14}) async {
    if (pantry.isEmpty) return [];
    final main = pantry.take(4).toList();
    final queries = <String>{main.join(' '), if (main.length > 1) main.take(2).join(' '), ...main.take(3)};
    final urls = <String>[];
    for (final lists in await Future.wait([
      for (final q in queries) _kwestia(q),
      _brave(main.join(' ')),
    ])) {
      for (final u in lists) {
        if (!urls.contains(u)) urls.add(u);
      }
    }
    final pages = await Future.wait([
      for (final u in urls.take(maxPages))
        importRecipeFromUrl(u, dio: _dio).then<Recipe?>((r) => r, onError: (_) => null)
    ]);
    final out = [
      for (final r in pages)
        if (r != null && r.ingredients.length >= 2) matchRecipe(r, pantry)
    ];
    out.sort((a, b) {
      final c = b.score.compareTo(a.score);
      return c != 0 ? c : a.missing.length.compareTo(b.missing.length);
    });
    return out;
  }
}
